  72: { id: 72, title: "التعريض بالدعاء لطلب الطعام أو الشراب", items: [
      { id: 7201, count: 1, periods: [], text: "((اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي)).", refs: ["حصن المسلم، باب «التعريض بالدعاء لطلب الطعام أو الشراب»"], review: true },
    ] },
  73: { id: 73, title: "الدعاء إذا أفطر عند أهل بيت", items: [
      { id: 7301, count: 1, periods: [], text: "((أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلاَئِكَةُ)).", refs: ["حصن المسلم، باب «الدعاء إذا أفطر عند أهل بيت»"], review: true },
    ] },
  74: { id: 74, title: "دعاء الصائم إذا حضر الطعام ولم يفطر", items: [
      { id: 7401, count: 1, periods: [], text: "((إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ، فَإِنْ كَانَ صَائِماً فَلْيُصَلِّ، وَإِنْ كَانَ مُفْطِراً فَلْيَطْعَمْ)) ، وَمَعْنَى فَلْيُصَلِّ أَيْ فَلْيَدْعُ.", refs: ["حصن المسلم، باب «دعاء الصائم إذا حضر الطعام ولم يفطر»"], review: true },
    ] },
  75: { id: 75, title: "ما يقول الصائم إذا سابه أحد", items: [
      { id: 7501, count: 1, periods: [], text: "((إِنِّي صَائِمٌ، إِنِّي صَائِمٌ)).", refs: ["حصن المسلم، باب «ما يقول الصائم إذا سابه أحد»"], review: true },
    ] },
  76: { id: 76, title: "الدعاء عند رؤية باكورة الثمر", items: [
      { id: 7601, count: 1, periods: [], text: "((اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا)).", refs: ["حصن المسلم، باب «الدعاء عند رؤية باكورة الثمر»"], review: true },
    ] },
  77: { id: 77, title: "دعاء العطاس", items: [
      { id: 7701, count: 1, periods: [], text: "((إِذَا عَطَسَ أَحَدُكُم فَلْيَقُلِ الْحَمْدُ لِلَّهِ، وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ: يَرْحَمُكَ اللَّهُ، فَإِذَا قَالَ لَهُ: يَرحَمُكَ اللَّهُ، فَلْيَقُلْ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ)).", refs: ["حصن المسلم، باب «دعاء العطاس»"], review: true },
    ] },
  79: { id: 79, title: "الدعاء للمتزوج", items: [
      { id: 7901, count: 1, periods: [], text: "((بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ)).", refs: ["حصن المسلم، باب «الدعاء للمتزوج»"], review: true },
    ] },
  80: { id: 80, title: "دعاء المتزوج و شراء الدابة", items: [
      { id: 8001, count: 1, periods: [], text: "إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً، أَوْ إِذَا اشْتَرَى خَادِماً فَلْيَقُلْ: ((اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ، وَإِذَا اشْتَرَى بَعِيراً فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ)).", refs: ["حصن المسلم، باب «دعاء المتزوج و شراء الدابة»"], review: true },
    ] },
  83: { id: 83, title: "دعاء من رأى مبتلى", items: [
      { id: 8301, count: 1, periods: [], text: "((الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلاَكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلاً)).", refs: ["حصن المسلم، باب «دعاء من رأى مبتلى»"], review: true },
    ] },
  84: { id: 84, title: "ما يقال في المجلس", items: [
      { id: 8401, count: 1, periods: [], text: "((عَنِ ابْنِ عُمَرَ رضي الله عنه قَاَلَ: كَانَ يُعَدُّ لِرَسُولِ اللَّهِ صلى الله عليه وسلم فِي الْمَجْلِسِ الوَاحِدِ مِائَةُ مَرَّةٍ مِنْ قَبْلِ أَنْ يَقُومَ: ((رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الغَفُورُ)).", refs: ["حصن المسلم، باب «ما يقال في المجلس»"], review: true },
    ] },
  85: { id: 85, title: "كفارة المجلس", items: [
      { id: 8501, count: 1, periods: [], text: "((سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ)).", refs: ["حصن المسلم، باب «كفارة المجلس»"], review: true },
    ] },
